@section('scripts')
<script>
const userBase = @json(url('dealer/users'));
function closeUserModal(id){document.getElementById(id).classList.add('hidden')}
function openUserCreate(){document.getElementById('user-form').reset();document.getElementById('user-form').action=userBase;document.getElementById('user-form-title').textContent='Create User';document.getElementById('create-user-helper').classList.remove('hidden');document.getElementById('user-form-modal').classList.remove('hidden')}
async function fetchUser(id){const response=await fetch(`${userBase}/${id}`);if(!response.ok)throw new Error('Unable to load user');return response.json()}
function renderUserFields(user){const fields=[['Name',user.name],['Email',user.email],['Phone',user.phone_number||'N/A'],['Dealer',user.dealer?.name||'N/A'],['Trial started',user.subscription_started_at?new Date(user.subscription_started_at).toLocaleString():'N/A'],['Trial ends',user.subscription_ends_at?new Date(user.subscription_ends_at).toLocaleString():'N/A'],['Approval',user.approval_status],['Created',new Date(user.created_at).toLocaleString()]];const container=document.getElementById('user-view-content');container.replaceChildren(...fields.map(([label,value])=>{const box=document.createElement('div');box.className='user-detail-box';const key=document.createElement('small');key.textContent=label;const text=document.createElement('strong');text.textContent=value;box.append(key,text);return box}))}
async function viewUser(id){document.getElementById('user-view-modal').classList.remove('hidden');renderUserFields(await fetchUser(id))}
async function editUser(id){const user=await fetchUser(id);document.getElementById('user-form').action=`${userBase}/${id}/update`;document.getElementById('user-form-title').textContent='Update User';document.getElementById('user-name').value=user.name;document.getElementById('user-email').value=user.email;document.getElementById('user-phone').value=user.phone_number||'';document.getElementById('create-user-helper').classList.add('hidden');document.getElementById('user-form-modal').classList.remove('hidden')}
</script>
@endsection
